(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const $$ = (s) => [...document.querySelectorAll(s)];
  const weapons = [
    {id:'pulse',name:'PULSE 9',type:'PISTOLA TÁTICA',price:0,damage:34,rate:310,mag:12,reserve:60,accuracy:1,art:'╱━▰',desc:'Confiável, leve e pronta para qualquer situação.', stats:[72,66,87],owned:true},
    {id:'viper',name:'VIPER SMG',type:'SUBMETRALHADORA',price:700,damage:21,rate:115,mag:28,reserve:112,accuracy:.9,art:'╱━━▰',desc:'Cadência brutal para dominar combates próximos.',stats:[58,95,62]},
    {id:'phantom',name:'PHANTOM 7',type:'RIFLE DE ASSALTO',price:1450,damage:48,rate:390,mag:20,reserve:80,accuracy:1.04,art:'╱━▰━',desc:'Precisão cirúrgica. Um disparo, um problema a menos.',stats:[91,72,78]},
    {id:'widow',name:'WIDOW MAKER',type:'CANHÃO DE PRECISÃO',price:2300,damage:100,rate:920,mag:5,reserve:25,accuracy:1.2,art:'╱━━━━▰',desc:'A última coisa que um hostil verá no escuro.',stats:[100,32,93]}
  ];
  const map = [
    '111111111111111','100000000000001','102000100020001','100000100000001','100000000000001','100200000002001','111000100011101','100000000000001','100200000002001','100000000000001','100000100000001','102000100020001','100000000000001','100000000000001','111111111111111'
  ];
  const enemySpawns = [{x:4.5,y:2.5},{x:10.5,y:2.5},{x:3.5,y:8.5},{x:11.5,y:8.5},{x:7.5,y:4.5},{x:7.5,y:10.5},{x:2.5,y:6.5},{x:12.5,y:6.5}];
  const player={x:7.5,y:7.5,a:-Math.PI/2,pitch:0,hp:100};
  let credits=1250, owned=['pulse'], equipped='pulse', enemies=[], wave=1, totalWaves=4, kills=0, earned=0, ammo=12,reserve=60;
  let mode='menu', lastTime=0, fireTimer=0, reloadTimer=0, waveWait=0, damageTimer=0, flashTimer=0, toastTimer=0, shootFlash=0, hitAt=0;
  let keys={}, move={x:0,y:0}, pointerLocked=false, dragging=false, dragX=0, dragY=0, audioCtx=null, columns=0, depthBuffer=[];
  let profile={};
  try { profile=JSON.parse(localStorage.getItem('neonBreachSave')||'{}'); credits=profile.credits??credits; owned=profile.owned||owned; equipped=profile.equipped||equipped; } catch(e){}
  weapons.forEach(w=>w.owned=owned.includes(w.id));
  const selected=()=>weapons.find(w=>w.id===equipped)||weapons[0];
  const save=()=>{localStorage.setItem('neonBreachSave',JSON.stringify({credits,owned,equipped}));updateCredits()};
  const fmt=n=>Math.floor(n).toLocaleString('pt-BR');
  function updateCredits(){ $('#topCredits').textContent=fmt(credits);$('#shopCredits').textContent=fmt(credits);$('#gameCredits').textContent=fmt(credits);$('#weaponCount').textContent=String(owned.length).padStart(2,'0'); }
  function screen(id){ $$('.screen').forEach(el=>el.classList.add('hidden')); if(id==='game'){$('#gameScreen').classList.remove('hidden');$('#gameScreen').querySelectorAll('.overlay').forEach(x=>x.classList.add('hidden'));}else $('#'+id+'Screen').classList.remove('hidden'); mode=id; }
  function showToast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.2;}
  function renderShop(){
    $('#shopGrid').innerHTML=weapons.map(w=>`<article class="weapon-card ${owned.includes(w.id)?'owned':''} ${equipped===w.id?'equipped':''}"><span class="weapon-class">${w.type}</span><div class="weapon-art">${w.art}</div><h3>${w.name}</h3><p>${w.desc}</p><div class="card-stats">${['DANO','CADÊNCIA','PRECISÃO'].map((s,i)=>`<div class="card-stat"><span>${s}</span><div class="stat-line"><i style="width:${w.stats[i]}%"></i></div></div>`).join('')}</div><div class="card-bottom"><span class="price">${owned.includes(w.id)?'✓ ADQUIRIDA':`₡ ${fmt(w.price)}`}</span><button class="card-action" data-weapon="${w.id}" ${owned.includes(w.id)?'disabled':''}>${owned.includes(w.id)?'NO INVENTÁRIO':'ADQUIRIR +'}</button></div></article>`).join('');
    $$('#shopGrid [data-weapon]').forEach(b=>b.onclick=()=>buy(b.dataset.weapon));updateCredits();
  }
  function buy(id){const w=weapons.find(x=>x.id===id);if(!w||owned.includes(id))return;if(credits<w.price){showToast('CRÉDITOS INSUFICIENTES — ELIMINE HOSTIS PARA GANHAR MAIS');return}credits-=w.price;owned.push(id);w.owned=true;save();renderShop();renderInventory();showToast(`${w.name} ADICIONADA AO INVENTÁRIO`);}
  function renderInventory(){
    const list=weapons.filter(w=>owned.includes(w.id));
    $('#inventoryList').innerHTML=list.map(w=>`<div class="inventory-item ${equipped===w.id?'active':''}" data-id="${w.id}"><div class="weapon-art">${w.art}</div><div><h3>${w.name}</h3><small>${w.type}</small></div><span class="equip-label">${equipped===w.id?'● EQUIPADA':'EQUIPAR ↗'}</span></div>`).join('');
